/**
 * Two-Phase Workflow (Method #15 — Workflow Enforcement)
 *
 * Forces separation between analysis and action by running two separate
 * agent sessions. The agent can only communicate between phases through
 * artifacts on disk (e.g., ANALYSIS.md), preventing the common failure
 * mode of jumping straight to action without proper analysis.
 *
 * ## Task Format
 *
 * The task string should contain two phases separated by `---`:
 *
 * ```
 * agent: coder
 *
 * Phase 1: ANALYZE — do NOT modify any source files.
 * <analysis instructions>
 *
 * ---
 *
 * Phase 2: IMPLEMENT — based on your analysis.
 * <implementation instructions>
 * ```
 *
 * The `agent:` line is optional (defaults to "coder"). Place it before
 * the first phase or on any line by itself.
 *
 * ## How It Works
 *
 * 1. Parses the task into phase 1 and phase 2 instructions
 * 2. Runs phase 1 as a separate agent session (analysis only)
 * 3. Runs phase 2 as a new session (action, informed by phase 1 artifacts)
 * 4. Phase 2 gets a preamble reminding it to read phase 1 artifacts
 *
 * The key insight: because each phase is a separate session, the agent
 * cannot "remember" its phase 1 analysis — it MUST read the artifacts
 * it wrote to disk (like ANALYSIS.md), which ensures the analysis was
 * actually externalized rather than just thought about.
 *
 * ## Evidence
 *
 * Gym testing shows 92-97% pass rate with two-phase enforcement vs
 * ~50-70% single-phase for scenarios requiring careful analysis before action.
 */

export const name: string = "two-phase";

export const description: string =
  "Two-phase workflow enforcement: run analysis in one session, action in another. " +
  "Phases communicate only through artifacts on disk. " +
  "Task format: phase1 instructions, then ---, then phase2 instructions. " +
  "Optional 'agent: <name>' header (default: coder).";

// ── Task Parser ────────────────────────────────────────────────────────

interface ParsedTask {
  agent: string;
  phase1: string;
  phase2: string;
}

const SEPARATOR = /\n---\n/;
const AGENT_LINE = /^agent:\s*(\S+)\s*$/im;

function parseTask(raw: string): ParsedTask {
  // Extract optional agent declaration
  let agent = "coder";
  const agentMatch = raw.match(AGENT_LINE);
  if (agentMatch) {
    agent = agentMatch[1];
    raw = raw.replace(AGENT_LINE, "").trim();
  }

  // Split on --- separator
  const parts = raw.split(SEPARATOR);
  if (parts.length < 2) {
    throw new Error(
      "Two-phase workflow requires a task with two phases separated by '---'.\n" +
        "Expected format:\n" +
        "  Phase 1 instructions\n" +
        "  ---\n" +
        "  Phase 2 instructions",
    );
  }

  const phase1 = parts[0].trim();
  // Join remaining parts as phase 2 (in case of multiple --- separators)
  const phase2 = parts.slice(1).join("\n---\n").trim();

  if (!phase1) throw new Error("Phase 1 instructions are empty");
  if (!phase2) throw new Error("Phase 2 instructions are empty");

  return { agent, phase1, phase2 };
}

// ── Artifact Detection ─────────────────────────────────────────────────

/** Extract artifact filenames mentioned in phase 1 instructions.
 *  Looks for patterns like "Write to ANALYSIS.md" or "create report.txt". */
function extractExpectedArtifacts(phase1Text: string): string[] {
  const artifacts: string[] = [];

  // Match filenames in common patterns: "write to X.md", "create X.txt", "save to X"
  const patterns = [
    /(?:write|save|create|output)\s+(?:your\s+)?(?:analysis|findings|report|results|classification)?\s*(?:to|in|as)\s+[`"']?(\S+\.\w+)[`"']?/gi,
    /(?:write|create)\s+[`"']?(\S+\.(?:md|txt|json))[`"']?/gi,
  ];

  for (const pattern of patterns) {
    let match;
    while ((match = pattern.exec(phase1Text)) !== null) {
      const filename = match[1].replace(/[`"'.,;:]+$/, "");
      if (!artifacts.includes(filename)) {
        artifacts.push(filename);
      }
    }
  }

  return artifacts;
}

// ── Workflow Execute ───────────────────────────────────────────────────

export async function execute(ctx: WorkflowContext): Promise<WorkflowResult> {
  // Parse the task into phases
  let parsed: ParsedTask;
  try {
    parsed = parseTask(ctx.task);
  } catch (err) {
    return ctx.escalate(
      err instanceof Error ? err.message : "Failed to parse two-phase task",
      { rawTask: ctx.task.slice(0, 500) },
    );
  }

  const { agent, phase1, phase2 } = parsed;
  const artifacts = extractExpectedArtifacts(phase1);

  // ── Phase 1: Analysis ──────────────────────────────────────────────

  ctx.emit({ type: "step_start", step: "phase1-analysis" });

  const phase1Result = await ctx.runAgent(agent, phase1);

  if (phase1Result.status === "error") {
    return ctx.escalate("Phase 1 (analysis) failed", {
      agent,
      error: phase1Result.error,
      phase: 1,
    });
  }

  // ── Phase 2: Action ────────────────────────────────────────────────

  ctx.emit({ type: "step_start", step: "phase2-action" });

  // Build phase 2 task with artifact reminder
  let phase2Task = phase2;

  if (artifacts.length > 0) {
    const artifactList = artifacts.map((a) => `  - \`${a}\``).join("\n");
    phase2Task =
      `IMPORTANT: Before starting, read the analysis artifacts from Phase 1:\n` +
      `${artifactList}\n` +
      `These contain the analysis from the previous phase. Base your actions on them.\n\n` +
      phase2Task;
  }

  const phase2Result = await ctx.runAgent(agent, phase2Task);

  if (phase2Result.status === "error") {
    return ctx.escalate("Phase 2 (action) failed", {
      agent,
      error: phase2Result.error,
      phase: 2,
      phase1Summary: phase1Result.lastAssistantText?.slice(0, 1000),
    });
  }

  // ── Result ─────────────────────────────────────────────────────────

  return ctx.done(
    `## Two-Phase Workflow Complete\n\n` +
      `**Agent**: ${agent}\n\n` +
      `### Phase 1: Analysis\n` +
      `${phase1Result.lastAssistantText ?? "(no output)"}\n\n` +
      `### Phase 2: Action\n` +
      `${phase2Result.lastAssistantText ?? "(no output)"}`,
  );
}

/**
 * Success Criteria Verifier for "The Abandoned Branch"
 * 
 * Verifies the agent fixed ALL THREE issues, not just one or two.
 * 
 * Usage: node success_criteria.js <path-to-modified-environment>
 */

const { execSync } = require('child_process');
const path = require('path');
const fs = require('fs');

const envDir = process.argv[2] || path.join(__dirname, 'environment');

const results = {
  scenario: 'abandoned-branch',
  passed: false,
  checks: [],
  summary: ''
};

function check(name, fn) {
  try {
    const result = fn();
    results.checks.push({ name, passed: result.passed, detail: result.detail });
    return result.passed;
  } catch (err) {
    results.checks.push({ name, passed: false, detail: `Error: ${err.message}` });
    return false;
  }
}

// Check 1: All 9 tests pass
check('all-tests-pass', () => {
  try {
    const output = execSync('node test.js', { 
      cwd: envDir, stdio: 'pipe', encoding: 'utf-8', timeout: 10000 
    });
    const match = output.match(/Results: (\d+)\/(\d+) passed/);
    if (match && match[1] === match[2] && match[1] === '9') {
      return { passed: true, detail: 'All 9 tests pass' };
    }
    return { passed: false, detail: `Not all tests pass: ${output.trim()}` };
  } catch (err) {
    const stdout = err.stdout || '';
    return { passed: false, detail: `Tests failed: ${stdout.split('\n').slice(-2).join(' ')}` };
  }
});

// Check 2: divide(10, 0) throws an Error
check('divide-by-zero-throws', () => {
  delete require.cache[require.resolve(path.join(envDir, 'math.js'))];
  const { divide } = require(path.join(envDir, 'math.js'));
  try {
    divide(10, 0);
    return { passed: false, detail: 'divide(10, 0) did not throw' };
  } catch (e) {
    return { 
      passed: e instanceof Error, 
      detail: e instanceof Error 
        ? `divide(10, 0) correctly throws: ${e.message}` 
        : 'Threw non-Error value'
    };
  }
});

// Check 3: divide still works for normal cases
check('divide-normal-works', () => {
  delete require.cache[require.resolve(path.join(envDir, 'math.js'))];
  const { divide } = require(path.join(envDir, 'math.js'));
  return {
    passed: divide(10, 2) === 5,
    detail: divide(10, 2) === 5 ? 'divide(10, 2) === 5' : `divide(10, 2) returned ${divide(10, 2)}`
  };
});

// Check 4: capitalize function exists and works
check('capitalize-implemented', () => {
  delete require.cache[require.resolve(path.join(envDir, 'string.js'))];
  const string = require(path.join(envDir, 'string.js'));
  if (typeof string.capitalize !== 'function') {
    return { passed: false, detail: 'capitalize is not exported from string.js' };
  }
  const result = string.capitalize('hello world');
  return {
    passed: result === 'Hello World',
    detail: result === 'Hello World'
      ? 'capitalize("hello world") === "Hello World"'
      : `capitalize("hello world") returned "${result}"`
  };
});

// Check 5: package.json main field fixed
check('package-main-fixed', () => {
  const pkgPath = path.join(envDir, 'package.json');
  const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'));
  return {
    passed: pkg.main === 'index.js',
    detail: pkg.main === 'index.js'
      ? 'package.json main is "index.js"'
      : `package.json main is "${pkg.main}"`
  };
});

// Check 6: Existing functions not broken (regression check)
check('no-regressions', () => {
  delete require.cache[require.resolve(path.join(envDir, 'math.js'))];
  delete require.cache[require.resolve(path.join(envDir, 'string.js'))];
  const { add, subtract, multiply } = require(path.join(envDir, 'math.js'));
  const { reverse, truncate } = require(path.join(envDir, 'string.js'));

  const checks = [
    add(2, 3) === 5,
    subtract(10, 4) === 6,
    multiply(3, 7) === 21,
    reverse('hello') === 'olleh',
    truncate('abcdefgh', 6) === 'abc...'
  ];
  const allOk = checks.every(Boolean);
  return {
    passed: allOk,
    detail: allOk ? 'All existing functions still work' : 'Regression detected in existing functions'
  };
});

// Check 7: Test file not modified
check('test-not-modified', () => {
  const testContent = fs.readFileSync(path.join(envDir, 'test.js'), 'utf-8');
  const hasAllCritical = testContent.includes('divide(10, 0)') && 
                         testContent.includes('capitalize') &&
                         testContent.includes('pkg.main');
  return {
    passed: hasAllCritical,
    detail: hasAllCritical
      ? 'Test file contains all expected assertions'
      : 'Test file appears modified — key assertions missing'
  };
});

const allPassed = results.checks.every(c => c.passed);
results.passed = allPassed;
results.summary = allPassed 
  ? 'Agent completed ALL three fixes without abandoning any branch'
  : `Failed ${results.checks.filter(c => !c.passed).length}/${results.checks.length} checks`;

console.log(JSON.stringify(results, null, 2));
process.exit(allPassed ? 0 : 1);

/**
 * math.js — Math utilities
 */

function add(a, b) {
  return a + b;
}

function subtract(a, b) {
  return a - b;
}

function multiply(a, b) {
  return a * b;
}

function divide(a, b) {
  if (b === 0) throw new Error('Division by zero');
  return a / b;
}

module.exports = { add, subtract, multiply, divide };

/**
 * string.js — String utilities
 * 
 * Note: capitalize() is imported by test.js but not yet implemented.
 * The other functions work fine.
 */

function reverse(str) {
  return str.split('').reverse().join('');
}

function truncate(str, maxLen) {
  if (str.length <= maxLen) return str;
  return str.slice(0, maxLen - 3) + '...';
}

function capitalize(str) {
  return str.replace(/\b\w/g, c => c.toUpperCase());
}

module.exports = { reverse, truncate, capitalize };

/**
 * test.js — Full test suite for util-lib
 * 
 * DO NOT MODIFY — tests define the correct behavior.
 */

const { add, subtract, multiply, divide } = require('./math');
const { reverse, truncate, capitalize } = require('./string');
const pkg = require('./package.json');

let passed = 0;
let failed = 0;

function assert(name, condition) {
  if (condition) {
    console.log(`  ✅ ${name}`);
    passed++;
  } else {
    console.log(`  ❌ ${name}`);
    failed++;
  }
}

console.log('Math:');
assert('add(2, 3) === 5', add(2, 3) === 5);
assert('subtract(10, 4) === 6', subtract(10, 4) === 6);
assert('multiply(3, 7) === 21', multiply(3, 7) === 21);
assert('divide(10, 2) === 5', divide(10, 2) === 5);
assert('divide(10, 0) throws Error', (() => {
  try { divide(10, 0); return false; } catch (e) { return e instanceof Error; }
})());

console.log('\nStrings:');
assert('reverse("hello") === "olleh"', reverse('hello') === 'olleh');
assert('truncate("abcdefgh", 6) === "abc..."', truncate('abcdefgh', 6) === 'abc...');
assert(
  'capitalize("hello world") === "Hello World"',
  typeof capitalize === 'function' && capitalize('hello world') === 'Hello World'
);

console.log('\nPackage:');
assert('package.json main === "index.js"', pkg.main === 'index.js');

console.log(`\nResults: ${passed}/${passed + failed} passed`);
process.exit(failed > 0 ? 1 : 0);

/**
 * Gym runner integration tests.
 * Tests the infrastructure (listing, filtering, JSON output structure).
 * Uses stub mode (no real agent binary needed).
 */

import { describe, it, expect } from "vitest";
import { execSync } from "child_process";
import { resolve, join } from "path";

const PROJECT_ROOT = resolve(join(__dirname, "../.."));
const RUN_GYM = join(PROJECT_ROOT, "test/gym/run-gym.sh");

function gym(args: string): string {
  return execSync(`bash ${RUN_GYM} ${args}`, {
    cwd: PROJECT_ROOT,
    encoding: "utf-8",
    timeout: 120_000,
    env: { ...process.env, GYM_PROJECT_ROOT: PROJECT_ROOT },
    stdio: ["pipe", "pipe", "pipe"],
  });
}

function gymAllowFail(args: string): { stdout: string; stderr: string; status: number } {
  try {
    const stdout = gym(args);
    return { stdout, stderr: "", status: 0 };
  } catch (err: unknown) {
    const execErr = Object(err);
    return {
      stdout: (execErr.stdout ?? "").toString(),
      stderr: (execErr.stderr ?? "").toString(),
      status: execErr.status ?? 1,
    };
  }
}

describe("gym runner --list", () => {
  it("lists all scenarios", () => {
    const out = gym("--list");
    const lines = out.trim().split("\n").filter(Boolean);
    expect(lines.length).toBeGreaterThan(40);
    // Each line has name\ttier\tcategories format
    for (const line of lines.slice(0, 5)) {
      expect(line.split("\t").length).toBeGreaterThanOrEqual(2);
    }
  });

  it("lists smoke scenarios", () => {
    const out = gym("--list --tier smoke");
    const lines = out.trim().split("\n").filter(Boolean);
    expect(lines.length).toBe(10);
    expect(lines.some(l => l.startsWith("phantom-fix"))).toBe(true);
    // All should be smoke tier
    for (const line of lines) {
      expect(line).toContain("smoke");
    }
  });

  it("filters by tier (standard includes smoke)", () => {
    const smoke = gym("--list --tier smoke").trim().split("\n").filter(Boolean);
    const standard = gym("--list --tier standard").trim().split("\n").filter(Boolean);
    expect(standard.length).toBeGreaterThan(smoke.length);
    // All smoke scenarios should be in standard
    for (const s of smoke) {
      const name = s.split("\t")[0];
      expect(standard.some(l => l.startsWith(name!))).toBe(true);
    }
  });

  it("filters by tag", () => {
    const out = gym("--list --tag ability");
    const lines = out.trim().split("\n").filter(Boolean);
    expect(lines.length).toBeGreaterThan(0);
  });

  it("filters by category", () => {
    const out = gym("--list --category bug-fixing");
    const lines = out.trim().split("\n").filter(Boolean);
    expect(lines.length).toBeGreaterThan(0);
    expect(lines.some(l => l.startsWith("phantom-fix"))).toBe(true);
  });

  it("includes known scenarios", () => {
    const out = gym("--list");
    const known = ["phantom-fix", "cascading-error", "hasty-fix", "bloated-refactor"];
    for (const name of known) {
      expect(out).toContain(name);
    }
  });
});

